mapper.select:
SELECT c.conversation_id, IF(c.conversation_user_a_id = #{userId}, c.conversation_user_b_id, c.conversation_user_a_id) AS peer_user_id, u.user_nickname AS peer_nickname, c.conversation_title, m.message_text AS last_message_text, m.create_time AS last_message_time, IFNULL(x.unread_count, 0) AS unread_count, c.create_time FROM ch_conversation c LEFT JOIN ch_user u ON u.user_id = IF(c.conversation_user_a_id = #{userId}, c.conversation_user_b_id, c.conversation_user_a_id) AND u.user_is_delete = 0 LEFT JOIN ch_message m ON m.message_id = (SELECT MAX(m2.message_id) FROM ch_message m2 WHERE m2.message_conversation_id = c.conversation_id) LEFT JOIN (SELECT message_conversation_id, COUNT(*) AS unread_count FROM ch_message WHERE message_receive_user_id = #{userId} AND message_is_read = 0 GROUP BY message_conversation_id) x ON x.message_conversation_id = c.conversation_id WHERE (c.conversation_user_a_id = #{userId} OR c.conversation_user_b_id = #{userId})
AND (c.create_time < #{cursorTime} OR (c.create_time = #{cursorTime} AND c.conversation_id < #{cursorId}))
ORDER BY c.create_time DESC, c.conversation_id DESC LIMIT #{pageSize}
